Here's an Express endpoint for uploading avatar images:

```javascript
const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs').promises;

const app = express();

// Configure storage
const storage = multer.diskStorage({
  destination: async (req, file, cb) => {
    const uploadsDir = path.join(__dirname, 'uploads/avatars');
    await fs.mkdir(uploadsDir, { recursive: true });
    cb(null, uploadsDir);
  },
  filename: (req, file, cb) => {
    // Sanitize filename, preserve extension
    const ext = path.extname(file.originalname);
    const name = `${Date.now()}-${Math.random().toString(36).slice(2)}${ext}`;
    cb(null, name);
  }
});

// Filter to accept only images
const fileFilter = (req, file, cb) => {
  const allowed = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];
  if (allowed.includes(file.mimetype)) {
    cb(null, true);
  } else {
    cb(new Error('Only image files are allowed'), false);
  }
};

// Create multer instance
const upload = multer({
  storage,
  fileFilter,
  limits: { fileSize: 5 * 1024 * 1024 } // 5MB max
});

// Avatar upload endpoint
app.post('/api/avatar', upload.single('avatar'), (req, res) => {
  if (!req.file) {
    return res.status(400).json({ error: 'No file uploaded' });
  }

  res.json({
    message: 'Avatar uploaded successfully',
    filename: req.file.filename,
    path: `/uploads/avatars/${req.file.filename}`,
    size: req.file.size
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    return res.status(400).json({ error: err.message });
  }
  if (err) {
    return res.status(400).json({ error: err.message });
  }
  next();
});

// Serve uploaded files
app.use('/uploads', express.static('uploads'));

app.listen(3000, () => console.log('Server running on port 3000'));
```

**Key features:**
- **Storage**: Saves to `uploads/avatars/` with timestamp + random suffix to avoid collisions
- **File validation**: Only allows JPEG, PNG, WebP, and GIF; rejects other types
- **Size limit**: 5MB max (adjust as needed)
- **Error handling**: Catches multer errors and invalid uploads
- **Static serving**: Uploaded files accessible via `/uploads/avatars/{filename}`

**Install dependency:**
```bash
npm install multer
```

**Usage:**
```bash
curl -F "avatar=@image.png" http://localhost:3000/api/avatar
```
